  "Right answer!": ["答对了！", "सही जवाब!", "¡Respuesta correcta!", "إجابة صحيحة!", "Bonne réponse !", "সঠিক উত্তর!", "Resposta certa!", "Правильно!", "صحیح جواب!", "答啱咗！", "Jawaban benar!"],
  "Line complete!": ["连成一线！", "लाइन पूरी!", "¡Línea completa!", "اكتمل الصف!", "Ligne complète !", "লাইন সম্পূর্ণ!", "Linha completa!", "Линия собрана!", "لائن مکمل!", "連成一線！", "Satu garis lengkap!"],
  "New lines!": ["新连线！", "नई लाइनें!", "¡Líneas nuevas!", "صفوف جديدة!", "Nouvelles lignes !", "নতুন লাইন!", "Linhas novas!", "Новые линии!", "نئی لائنیں!", "新連線！", "Garis baru!"],
